#include "vehicle_dynamics.hpp"
#include <cmath>
#include <iostream>
#include <stdexcept>
using namespace ofo;
void need(bool b,const char*m){if(!b)throw std::runtime_error(m);}
int main(){try{auto t=combined_tire_impulse(100,100,10,10);need(t.longitudinal>5&&t.lateral>5,"full throttle must leave physical lateral grip for cornering");need(t.longitudinal*t.longitudinal+t.lateral*t.lateral<=100.001f,"combined force stays inside friction circle");auto braking=combined_tire_impulse(-100,50,20,10);need(braking.longitudinal<0&&braking.lateral>0,"braking and cornering share the friction ellipse");auto air=combined_tire_impulse(100,100,0,0);need(air.longitudinal==0&&air.lateral==0,"airborne tires generate no grip");VehicleConfig c;HandlingTuning tune(c);float a=0,b=0;auto first=steering_step(a,1,0,c,tune,.01f);need(first>0&&first<.08f,"bounded steering rate");for(int i=1;i<100;i++)steering_step(a,1,0,c,tune,.01f);for(int i=0;i<50;i++)steering_step(b,1,0,c,tune,.02f);need(std::abs(a-b)<.0001f,"steering response independent of update subdivision");float partial=0;for(int i=0;i<100;i++)steering_step(partial,.25f,0,c,tune,.01f);need(std::abs(partial-.25f)<.0001f,"quarter analog input retains quarter authored steering authority");float reverse=1;steering_step(reverse,-1,0,c,tune,.1f);need(reverse<1-tune.steering_rates[1]*.1f,"countersteer crosses the old direction faster than passive return");float revA=1,revB=1;for(int i=0;i<80;i++)steering_step(revA,-1,0,c,tune,.005f);for(int i=0;i<20;i++)steering_step(revB,-1,0,c,tune,.02f);need(std::abs(revA-revB)<.0001f,"countersteer response independent of update subdivision at center crossing");float low=steering_step(a,1,0,c,tune,.01f),fast=steering_step(b,1,35,c,tune,.01f);need(fast>0&&std::abs(fast/low-(1-c.steering_reduction*35/c.steering_limit))<.0001f,"authored speed reduction applies without an extra comfort multiplier");need(std::abs(tire_brush_response(0.f))<1e-6f&&std::abs(tire_brush_response(1.f)-1)<1e-6f,"brush zero slip and authored peak");need(tire_brush_response(-.5f)<0,"brush opposes signed slip");for(int i=-100;i<=100;++i){float x=i*.01f,r=tire_lateral_response(x);need(std::abs(r)<=1.00001f&&x*r>=0,"lateral brush dissipates slip within authored grip");need(std::abs(r-tire_lateral_response(-x)*-1)<1e-6f,"lateral response is symmetric");if(i<100)need(tire_lateral_response(x+.01f)>=r-1e-6f,"lateral grip grows progressively");}
need(tire_lateral_response(.1f)>tire_brush_response(.1f)&&tire_lateral_response(1)==1,"firmer small-slip response preserves authored peak");auto drag=aerodynamic_drag(c,{2,-3,4});need(drag.x<0&&drag.y>0&&drag.z<0,"all authored drag axes oppose local motion");auto roll=lateral_roll_point({1,-1,0},{0,1,0});need(std::abs(roll.y+.55f)<1e-5f&&roll.x==1,"adapted roll center reduces lateral overturning lever without changing track width");WheelConfig w;w.k=1000;w.rest=.3f;w.min=0;w.bump=100;w.rebound=200;need(std::abs(suspension_force(w,.2f,-.1f,1000,0)-160)<.01f,"5cm preload adds k*0.05 force while native bump damping is preserved");std::cout<<"combined throttle/brake/cornering grip passed\n";}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
